<template><cl-crud ref="Crud"><cl-row><cl-refresh-btn/><cl-add-btn/><cl-multi-delete-btn/><cl-flex1/><cl-select prop="type" :options="types" placeholder="消息类型"/><cl-search-key placeholder="搜索手机号、标题或内容"/></cl-row><cl-row><cl-table ref="Table"/></cl-row><cl-row><cl-flex1/><cl-pagination/></cl-row><cl-upsert ref="Upsert"/></cl-crud></template>
<script setup lang="ts">
import { useCrud,useTable,useUpsert } from '@cool-vue/crud';import { useCool } from '/@/cool';defineOptions({name:'loan-notification'});const{service}=useCool();const types=[{label:'审核通知',value:'review'},{label:'还款提醒',value:'repayment'},{label:'系统消息',value:'system'}];const Table=useTable({columns:[{type:'selection',width:55},{label:'用户ID',prop:'userId',width:90},{label:'手机号',prop:'phone',minWidth:130},{label:'类型',prop:'type',dict:types,width:110},{label:'标题',prop:'title',minWidth:180},{label:'内容',prop:'content',minWidth:260,showOverflowTooltip:true},{label:'已读时间',prop:'readAt',minWidth:170},{label:'发送时间',prop:'createTime',minWidth:170},{type:'op',buttons:['delete'],width:80}]});const Upsert=useUpsert({items:[{label:'用户ID',prop:'userId',required:true,component:{name:'el-input-number',props:{min:1}}},{label:'消息类型',prop:'type',required:true,value:'system',component:{name:'el-radio-group',options:types}},{label:'标题',prop:'title',required:true,component:{name:'el-input',props:{maxlength:120}}},{label:'消息内容',prop:'content',required:true,component:{name:'el-input',props:{type:'textarea',rows:5}}},{label:'跳转地址',prop:'link',component:{name:'el-input',props:{placeholder:'/messages'}}}]});const Crud=useCrud({service:(service as any).loan.notification},app=>app.refresh());
</script>
